--region handler
---cell点击回调
function DreamAdventuresMapStageCell:CellOnClickHandler()
    local cellData = self:GetCellData()
    if checkInt(cellData.status) == DreamAdventuresConstants.QuestStatus.LOCK then
        GameUtils.Toast(localize("通关最新关卡后解锁"))
        return
    end
    
    if self:GetClickCB() then
        local cb = self:GetClickCB()
        local index = self:GetIndex()
        cb(index)
    end
end
