--region private
---刷新UI
function DreamAdventuresMapStageCell:RefreshUI(cellData, isSelected)
    local isStory = checkInt(cellData.type) == DreamAdventuresConstants.QuestPlotType.STORY
    local isLock = checkInt(cellData.status) == DreamAdventuresConstants.QuestStatus.LOCK
    local isGet = checkInt(cellData.status) == DreamAdventuresConstants.QuestStatus.PASS
    local isNew = checkInt(cellData.status) == DreamAdventuresConstants.QuestStatus.NOW
    
    CfUtils.FillText(self.TxtName, cellData.name)

    if isLock then 
        CfUtils.SetUISwitchImage(self.ImgBg, 1)
        CfUtils.SetActive(self.ImgIcon, false)
        CfUtils.SetActive(self.ImgLock, true)
    else
        if isSelected then
            CfUtils.SetUISwitchImage(self.ImgBg, 3)
        else
            CfUtils.SetUISwitchImage(self.ImgBg, 2)
        end
        CfUtils.SetActive(self.ImgIcon, true)
        CfUtils.SetActive(self.ImgLock, false)
        if isStory then
            CfUtils.SetUISwitchImage(self.ImgIcon, 2)
        else
            CfUtils.SetUISwitchImage(self.ImgIcon, 1)
        end
    end
    CfUtils.SetActive(self.ImgBgSelect, isSelected)
    CfUtils.SetActive(self.ImgBgGet, isGet)
    CfUtils.SetActive(self.ImgNew, isNew)

    local animName = isSelected and "ActivityDreamAdventureslStoryMap_Cell_Select" or "ActivityDreamAdventureslStoryMap_Cell_Default"
    if self._aniCo ~= nil then
        cs_coroutine.stop(self._aniCo)
    end
    self._aniCo = cs_coroutine.start(function()
        coroutine.yield(Yielders.EndOfFrame)
        CfUtils.PlayAnimation(self.controller.gameObject, animName)
    end)
    
end
--endregion private

